        {"条款": "劳动报酬", "内容": "乙方月工资为人民币[X]元（税前），其中基本工资[X]元，绩效工资[X]元。每月[X]日以银行转账方式发放。", "依据": "《劳动合同法》第17/30条"},
        {"条款": "社会保险", "内容": "甲方依法为乙方缴纳养老保险、医疗保险、失业保险、工伤保险、生育保险和住房公积金。", "依据": "《社会保险法》第58条"},
        {"条款": "解除与终止", "内容": "双方解除或终止劳动合同，应依法办理离职手续。甲方违法解除的，应按经济补偿标准的二倍支付赔偿金。", "依据": "《劳动合同法》第46-48/87条"},
    ],
    "NDA": [
        {"条款": "保密信息定义", "内容": "保密信息包括但不限于：技术资料、商业计划、客户信息、财务数据、营销策略等双方标注为'保密'或按其性质应视为保密的一切信息。", "依据": "《民法典》第501条"},
        {"条款": "保密义务", "内容": "接收方应对保密信息严格保密，未经披露方书面同意，不得向第三方披露，且仅限于本协议目的使用。", "依据": "《民法典》第501条"},
        {"条款": "违约赔偿", "内容": "违反保密义务的，违约方应赔偿守约方因此遭受的一切损失，包括但不限于直接损失、间接损失和合理的维权费用。", "依据": "《民法典》第584-585条"},
    ],
}

def skill_function(input_data: Dict[str, Any]) -> Dict[str, Any]:
    try:
        contract_type = input_data.get("contract_type", "")
        scenario = input_data.get("scenario", "")

        clauses = CLAUSE_LIBRARY.get(contract_type, [])
        if not clauses:
            return {"status": "success", "result": {"提示": f"暂无'{contract_type}'的标准条款库", "可选类型": list(CLAUSE_LIBRARY.keys())}}

        return {
            "status": "success",
            "result": {
                "合同类型": contract_type,
                "推荐条款": clauses,
                "建议": [
                    "根据具体业务场景调整条款内容",
                    "金额/期限/数量等关键信息需填入实际值",
                    "建议请专业律师审核最终版本",
                ],
            },
        }
    except Exception as e:
        return {"status": "error", "message": str(e)}

if __name__ == "__main__":
    print(json.dumps(skill_function({"contract_type": "买卖合同"}), ensure_ascii=False, indent=2))

